"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["9710"],{19649(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.notas_do_enem.arquivo_fora_do_leiaute","status":422,"titulo":"O arquivo n\xe3o confere com o leiaute escolhido"},"descricao":{"codigo":"uniplus.selecao.notas_do_enem.arquivo_fora_do_leiaute","requisitos":["UNI-REQ-0174"],"oQueAconteceu":["A estrutura do arquivo n\xe3o corresponde ao leiaute escolhido: n\xfamero de campos diferente, CPF, n\xfamero de inscri\xe7\xe3o ou nota fora do formato, codifica\xe7\xe3o que n\xe3o \xe9 UTF-8, linha em branco no meio do arquivo, arquivo sem linhas, ou prova marcada como ausente com nota diferente de zero numa \xe1rea. O arquivo \xe9 recusado inteiro, sem gravar nenhuma nota, para que a nota de uma \xe1rea nunca seja gravada como se fosse de outra (UNI-REQ-0174). A mensagem de detalhe aponta a linha e a coluna, nunca o conte\xfado, porque o arquivo traz dados pessoais."],"comoResolver":["Confira se o leiaute escolhido \xe9 o do arquivo: o retorno de 20 campos vale para as edi\xe7\xf5es a partir de 2024. N\xe3o edite o arquivo para faz\xea-lo passar. Se o INEP mudou o formato e o leiaute certo n\xe3o est\xe1 no cat\xe1logo, acione a equipe t\xe9cnica. Quando a recusa \xe9 de prova ausente com nota, o arquivo est\xe1 incoerente: o caminho \xe9 gerar de novo o arquivo com os CPFs, envi\xe1-lo \xe0 plataforma do INEP e importar o retorno. Se o novo retorno continuar incoerente, acione a equipe t\xe9cnica."],"ondeAparece":["Importa\xe7\xe3o do arquivo de retorno do INEP"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Notas do enem"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);